//! maplibre-native-ffi's C API (https://github.com/maplibre/maplibre-native-ffi,
//! headers in ffi/include) implemented on the Rust port, as a static library
//! that can stand in for the ffi's C++ `maplibre_native_c` library.
//!
//! Ports maplibre-native-ffi `src/` (the C API layer over the C++ core) where
//! //ffi implements a function; every other function of the API is a stub in
//! `stubs.rs` (generated by tools/gen_stubs.py) that returns
//! MLN_STATUS_UNSUPPORTED.

// FFI: every export takes raw pointers from C (PORTING.md allows `unsafe`
// for FFI).
#![allow(clippy::missing_safety_doc)]

mod base;
mod delivery;
mod diagnostics;
mod handles;
mod layout;
mod map;
mod runtime;
mod session;
mod stubs;
mod types;
